# %% [markdown]
# ## Step 8 — Run Full Eval Suite (Both Versions on All 3 Candidates)
#
# Now evaluate both v1 and v2 on ALL 3 candidates to get a robust comparison.

# %%
import statistics

async def evaluate_all(candidate_data, summaries_by_version, version_name):
    """Run LLM judge on all candidates for a given prompt version."""
    results = {}
    
    for candidate in candidate_data:
        cid = candidate["id"]
        summary = summaries_by_version[cid]
        
        judge_prompt = f"""You are an expert HR evaluator. Review this candidate's CV, the generated summary, and recommendation.

CV: {candidate['cv_snippet']}

Generated Summary: {summary['summary']}
Recommendation: {summary['recommendation']}

Score on TWO criteria (each 1-5):

1. Summary Quality: Does it capture key strengths clearly?
   5 = Concise, accurate, highlights relevant skills. Clear value.
   4 = Mostly clear, minor gaps or verbose.
   3 = Partially captures strengths, some inaccuracy.
   2 = Missing key info or notable inaccuracy.
   1 = Incomplete, inaccurate, unhelpful.

2. Recommendation Alignment: Does recommendation follow logically?
   5 = Well-justified, perfectly aligned.
   4 = Reasonable and mostly justified.
   3 = Somewhat justified.
   2 = Questionable or poorly justified.
   1 = Contradicts summary or clearly wrong.

JSON: {{"summary_quality": <1-5>, "recommendation_alignment": <1-5>, "reasoning": "<brief>"}}"""
        
        r = await lrn_llm.call(
            [{"role": "user", "content": judge_prompt}],
            system="You are a strict, fair evaluator. Give honest scores. Return valid JSON only.",
            max_tokens=150,
        )
        
        response_text = lrn_llm.text(r)
        try:
            scores = json.loads(response_text)
            results[cid] = scores
        except json.JSONDecodeError:
            results[cid] = {"summary_quality": 0, "recommendation_alignment": 0, "error": "Parse error"}
    
    return results

print("Evaluating v1 (baseline) on all 3 candidates...")
results_v1_all = await evaluate_all(CANDIDATES, SUMMARIES_V1, "v1")

print("Evaluating v2 (new) on all 3 candidates...")
results_v2_all = await evaluate_all(CANDIDATES, SUMMARIES_V2, "v2")

print("\n✅ Eval complete!")

# %% [markdown]
# ## Step 9 — Compute Aggregate Scores & Decision
#
# Compute mean scores across all candidates and criteria. Determine if v2 should ship or if v1 should stay in production.

# %%
# Extract all scores
v1_quality_scores = [results_v1_all[cid]["summary_quality"] for cid in results_v1_all if "summary_quality" in results_v1_all[cid]]
v1_alignment_scores = [results_v1_all[cid]["recommendation_alignment"] for cid in results_v1_all if "recommendation_alignment" in results_v1_all[cid]]

v2_quality_scores = [results_v2_all[cid]["summary_quality"] for cid in results_v2_all if "summary_quality" in results_v2_all[cid]]
v2_alignment_scores = [results_v2_all[cid]["recommendation_alignment"] for cid in results_v2_all if "recommendation_alignment" in results_v2_all[cid]]

print("EVAL COMPARISON REPORT")
print("=" * 60)
print()
print(f"{'Metric':<30} {'v1 (Baseline)':<15} {'v2 (New)':<15}")
print("-" * 60)

# Summary Quality
if v1_quality_scores and v2_quality_scores:
    v1_q_mean = statistics.mean(v1_quality_scores)
    v2_q_mean = statistics.mean(v2_quality_scores)
    diff_q = v2_q_mean - v1_q_mean
    print(f"Summary Quality          {v1_q_mean:.2f}/5          {v2_q_mean:.2f}/5")
    print(f"  Change: {diff_q:+.2f}")
    print()

# Recommendation Alignment
if v1_alignment_scores and v2_alignment_scores:
    v1_a_mean = statistics.mean(v1_alignment_scores)
    v2_a_mean = statistics.mean(v2_alignment_scores)
    diff_a = v2_a_mean - v1_a_mean
    print(f"Recommendation Alignment {v1_a_mean:.2f}/5          {v2_a_mean:.2f}/5")
    print(f"  Change: {diff_a:+.2f}")
    print()

# Overall
if v1_quality_scores and v1_alignment_scores and v2_quality_scores and v2_alignment_scores:
    v1_all = v1_quality_scores + v1_alignment_scores
    v2_all = v2_quality_scores + v2_alignment_scores
    v1_overall = statistics.mean(v1_all)
    v2_overall = statistics.mean(v2_all)
    diff_overall = v2_overall - v1_overall
    print(f"Overall (all criteria)    {v1_overall:.2f}/5          {v2_overall:.2f}/5")
    print(f"  Change: {diff_overall:+.2f}")
    print()

print("=" * 60)
print()

# Ship decision
if diff_overall > 0.2:
    decision = "SHIP v2 - Quality improved significantly"
    status = "✅"
elif diff_overall < -0.2:
    decision = "BLOCK v2 - Quality regressed significantly"
    status = "❌"
else:
    decision = "STABLE - v1 and v2 are comparable"
    status = "⏸"

print(f"{status} DECISION: {decision}")

